import Layout from "./Layout";
import logo from "../../assets/logo1.png";

export default function AccountIntern() {
  const [userData, setUserData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isBadgeModalOpen, setIsBadgeModalOpen] = useState(false);
  const [isFlipped, setIsFlipped] = useState(false);
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [uploadError, setUploadError] = useState(null);
  const [uploadSuccess, setUploadSuccess] = useState(null);
  const navigate = useNavigate();

  const currentDate = new Date("2025-03-22");
  const validityDate = new Date(currentDate);
  validityDate.setMonth(currentDate.getMonth() + 6);
  const formattedValidityDate = validityDate.toLocaleDateString("fr-FR", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  });

  useEffect(() => {
    const fetchUserData = async () => {
      const token = localStorage.getItem("token");
      const role = localStorage.getItem("role");

      if (!token || !role) {
        setError("Authentification requise. Veuillez vous connecter.");
        setIsLoading(false);
        navigate("/login");
        return;
      }

      try {
        const response = await axios.get(
          `${process.env.REACT_APP_API_URL}/api/auth/me`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Role: role,
            },
          }
        );

        if (response.data.success) {
          const user = {
            ...response.data.user,
            // Ensure decimal fields are parsed as numbers
            geographic_criteria: response.data.user.geographic_criteria
              ? parseFloat(response.data.user.geographic_criteria).toFixed(2)
              : "0.00",
            Note: response.data.user.Note
              ? parseFloat(response.data.user.Note).toFixed(2)
              : "0.00",
          };
          setUserData(user);
          if (response.data.user.image) {
            setImagePreview(`${process.env.REACT_APP_API_URL}${response.data.user.image}`);
          }
        } else {
          setError(response.data.message || "Échec de la récupération des données.");
        }
      } catch (err) {
        setError(err.response?.data?.message || "Une erreur s'est produite.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchUserData();
  }, [navigate]);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      // Validate file type and size
      const validTypes = ["image/jpeg", "image/png"];
      const maxSize = 5 * 1024 * 1024; // 5MB
      if (!validTypes.includes(file.type)) {
        setUploadError("Veuillez sélectionner une image JPEG ou PNG.");
        return;
      }
      if (file.size > maxSize) {
        setUploadError("L'image ne doit pas dépasser 5 Mo.");
        return;
      }
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
      setUploadError(null);
      setUploadSuccess(null);
    }
  };

  const handleImageUpload = async () => {
    if (!imageFile) {
      setUploadError("Veuillez sélectionner une image.");
      return;
    }

    const formData = new FormData();
    formData.append("image", imageFile);

    try {
      const token = localStorage.getItem("token");
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/interns/upload-image`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "intern",
            "Content-Type": "multipart/form-data",
          },
        }
      );

      if (response.data.success) {
        setUploadSuccess("Image téléchargée avec succès !");
        setUserData((prev) => ({
          ...prev,
          image: response.data.image,
        }));
        setImagePreview(`${process.env.REACT_APP_API_URL}${response.data.image}`);
        // Revoke temporary URL to prevent memory leaks
        if (imagePreview && imagePreview.startsWith("blob:")) {
          URL.revokeObjectURL(imagePreview);
        }
      } else {
        setUploadError(response.data.message || "Échec du téléchargement.");
      }
    } catch (err) {
      setUploadError(err.response?.data?.message || "Erreur lors du téléchargement.");
    }
  };

  const openBadgeModal = () => {
    setIsBadgeModalOpen(true);
    setIsFlipped(false);
  };

  const closeBadgeModal = () => {
    setIsBadgeModalOpen(false);
  };

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  const handleDownloadBadge = () => {
    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });
    const badgeContainer = document.getElementById("badge-container");
    const frontElement = document.getElementById("badge-front");
    const backElement = document.getElementById("badge-back");

    frontElement.style.visibility = "visible";
    backElement.style.visibility = "visible";
    frontElement.style.transform = "none";
    backElement.style.transform = "none";
    badgeContainer.style.transform = "none";

    const imgElement = frontElement.querySelector("img");
    if (!imgElement || !userData.image) {
      /* eslint-disable */console.error(...oo_tx(`1709345389_192_6_192_77_11`,"No image element found or no image data in badge-front"));
      alert("Aucune image disponible pour le badge.");
      // Reset badge visibility
      frontElement.style.visibility = isFlipped ? "hidden" : "visible";
      backElement.style.visibility = isFlipped ? "visible" : "hidden";
      badgeContainer.style.transform = isFlipped ? "rotateY(180deg)" : "rotateY(0deg)";
      return;
    }

    const captureFront = () => {
      html2canvas(frontElement, {
        scale: 2,
        backgroundColor: "#ffffff",
        logging: true,
        useCORS: true,
      })
        .then((frontCanvas) => {
          const frontImgData = frontCanvas.toDataURL("image/png");

          html2canvas(backElement, {
            scale: 2,
            backgroundColor: "#ffffff",
            logging: true,
            useCORS: true,
          })
            .then((backCanvas) => {
              const backImgData = backCanvas.toDataURL("image/png");

              const pageWidth = doc.internal.pageSize.getWidth();
              const badgeWidth = pageWidth / 2 - 10;
              const badgeHeight = (frontCanvas.height * badgeWidth) / frontCanvas.width;

              doc.addImage(frontImgData, "PNG", 5, 20, badgeWidth, badgeHeight);
              doc.addImage(backImgData, "PNG", pageWidth / 2 + 5, 20, badgeWidth, badgeHeight);

              doc.save(`Badge_${userData.First_Name}_${userData.Last_Name}.pdf`);

              // Reset badge visibility
              frontElement.style.visibility = isFlipped ? "hidden" : "visible";
              backElement.style.visibility = isFlipped ? "visible" : "hidden";
              badgeContainer.style.transform = isFlipped ? "rotateY(180deg)" : "rotateY(0deg)";
            })
            .catch((error) => {
              /* eslint-disable */console.error(...oo_tx(`1709345389_235_14_235_59_11`,"Error capturing back:", error));
              alert("Erreur lors de la capture du verso du badge");
              // Reset badge visibility
              frontElement.style.visibility = isFlipped ? "hidden" : "visible";
              backElement.style.visibility = isFlipped ? "visible" : "hidden";
              badgeContainer.style.transform = isFlipped ? "rotateY(180deg)" : "rotateY(0deg)";
            });
        })
        .catch((error) => {
          /* eslint-disable */console.error(...oo_tx(`1709345389_244_10_244_56_11`,"Error capturing front:", error));
          alert("Erreur lors de la capture du recto du badge");
          // Reset badge visibility
          frontElement.style.visibility = isFlipped ? "hidden" : "visible";
          backElement.style.visibility = isFlipped ? "visible" : "hidden";
          badgeContainer.style.transform = isFlipped ? "rotateY(180deg)" : "rotateY(0deg)";
        });
    };

    if (imgElement.complete && imgElement.naturalWidth !== 0) {
      captureFront();
    } else {
      imgElement.onload = () => {
        captureFront();
      };
      imgElement.onerror = () => {
        /* eslint-disable */console.error(...oo_tx(`1709345389_260_8_260_62_11`,"Image failed to load:", imgElement.src));
        alert("Erreur de chargement de l'image du badge.");
        frontElement.style.visibility = isFlipped ? "hidden" : "visible";
        backElement.style.visibility = isFlipped ? "visible" : "hidden";
        badgeContainer.style.transform = isFlipped ? "rotateY(180deg)" : "rotateY(0deg)";
      };
      imgElement.src = imgElement.src; // Trigger reload if necessary
    }
  };

  const getTranslatedRole = (role) => {
    return role === "intern" ? "Stagiaire" : role;
  };

  const renderUserDetails = () => {
    if (!userData) return null;

    const commonFields = [
      { label: "Email", value: userData.email },
      { label: "Rôle", value: getTranslatedRole(userData.role) },
      { label: "Créé le", value: new Date(userData.createdAt).toLocaleDateString("fr-FR") },
    ];

    const specificFields = [
      { label: "CFF", value: userData.CFF },
      { label: "Prénom", value: userData.First_Name },
      { label: "Nom", value: userData.Last_Name },
      { label: "Genre", value: userData.Gender === "Male" ? "Homme" : "Femme" },
      { label: "Nationalité", value: userData.Nationality },
      { label: "Secteur", value: userData.Sector },
      { label: "Ville d'origine", value: userData.hometown },
      { label: "Emplacement", value: userData.emplacement },
      { label: "Numéro de téléphone", value: userData.phoneNumber },
      { label: "Numéro de téléphone des parents", value: userData.parentPhoneNumber },
      // Add decimal fields if they exist
      { label: "Critère géographique", value: userData.geographic_criteria || "0.00" },
      { label: "Note", value: userData.Note || "0.00" },
    ];

    const allFields = [...specificFields, ...commonFields];

    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6">
        {allFields.map((field, index) => (
          <div key={index} className="mb-2">
            <p className="text-xs font-medium text-[#00717F] uppercase tracking-wider">
              {field.label}
            </p>
            <p className="text-xs sm:text-sm text-[#333333]">
              {field.value || "Non spécifié"}
            </p>
          </div>
        ))}
      </div>
    );
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-4 sm:py-6">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50"
        >
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 sm:p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h1 className="text-xl sm:text-2xl font-bold tracking-tight">
                  Mon compte
                </h1>
                <p className="text-white/80 mt-1 text-xs sm:text-sm">
                  Consultez vos informations personnelles
                </p>
              </div>
            </div>
          </div>

          <div className="p-4 sm:p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-48 sm:h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-8 w-8 text-[#00717F] animate-spin" />
                  <p className="text-gray-500 text-sm">Chargement des données...</p>
                </div>
              </div>
            ) : error ? (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
                className="p-3 sm:p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm"
              >
                <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-red-500 flex-shrink-0" />
                <p className="text-xs sm:text-sm text-red-700">{error}</p>
              </motion.div>
            ) : userData ? (
              <div className="space-y-6 sm:space-y-8">
                <div className="flex items-center gap-3 sm:gap-4 border-b border-[#C8A45D/30]/50 pb-3 sm:pb-4">
                  <UserCircle className="h-10 w-10 sm:h-12 sm:w-12 text-[#00717F] opacity-80" />
                  <div>
                    <h2 className="text-lg sm:text-xl font-semibold text-[#00717F]">
                      {`${userData.First_Name} ${userData.Last_Name}`}
                    </h2>
                    <p className="text-xs sm:text-sm text-[#00717F]">
                      Rôle: <span className="font-medium capitalize">{getTranslatedRole(userData.role)}</span>
                    </p>
                  </div>
                </div>

                {renderUserDetails()}

                <div className="space-y-3 sm:space-y-4">
                  <h3 className="text-base sm:text-lg font-semibold text-[#00717F]">
                    Photo de profil
                  </h3>
                  <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
                    <div className="w-20 h-20 sm:w-24 sm:h-24 rounded-full overflow-hidden bg-gray-200 flex items-center justify-center">
                      {imagePreview ? (
                        <img
                          src={imagePreview}
                          alt="Profile"
                          className="w-full h-full object-cover"
                          onError={() => {
                            setImagePreview(null);
                            setUploadError("Erreur de chargement de l'image.");
                          }}
                        />
                      ) : (
                        <span className="text-gray-500 text-xs sm:text-sm">Aucune image</span>
                      )}
                    </div>
                    <div className="space-y-2 w-full sm:w-auto">
                      <label
                        htmlFor="image-upload"
                        className="cursor-pointer bg-[#00717F] text-white py-1.5 sm:py-2 px-3 sm:px-4 rounded-md hover:bg-[#C8A45D] transition-colors flex items-center gap-2 text-xs sm:text-sm w-full sm:w-auto justify-center sm:justify-start"
                      >
                        <Upload className="h-3 w-3 sm:h-4 sm:w-4" />
                        Choisir une image
                      </label>
                      <input
                        id="image-upload"
                        type="file"
                        accept="image/jpeg,image/png"
                        onChange={handleImageChange}
                        className="hidden"
                      />
                      <button
                        onClick={handleImageUpload}
                        disabled={!imageFile}
                        className={`py-1.5 sm:py-2 px-3 sm:px-4 rounded-md text-xs sm:text-sm font-medium w-full sm:w-auto ${
                          imageFile
                            ? "bg-green-600 text-white hover:bg-green-700"
                            : "bg-gray-300 text-gray-500 cursor-not-allowed"
                        } transition-colors`}
                      >
                        Télécharger
                      </button>
                    </div>
                  </div>
                  {uploadError && (
                    <p className="text-red-600 text-xs sm:text-sm">{uploadError}</p>
                  )}
                  {uploadSuccess && (
                    <p className="text-green-600 text-xs sm:text-sm">{uploadSuccess}</p>
                  )}
                </div>

                <div className="flex flex-col sm:flex-row gap-3 sm:gap-4">
                  <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => navigate("/InternDashboard")}
                    className="bg-[#00717F] text-white py-2 sm:py-3 px-3 sm:px-4 rounded-md shadow-sm hover:bg-[#00717F] transition-colors duration-300 flex items-center justify-center gap-2 text-xs sm:text-sm font-medium"
                  >
                    Retour au tableau de bord
                  </motion.button>
                  <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={openBadgeModal}
                    className="bg-[#00717F] text-white py-2 sm:py-3 px-3 sm:px-4 rounded-md shadow-sm hover:bg-[#00717F] transition-colors duration-300 flex items-center justify-center gap-2 text-xs sm:text-sm font-medium"
                  >
                    Voir mon badge
                  </motion.button>
                </div>
              </div>
            ) : (
              <div className="flex flex-col justify-center items-center h-48 sm:h-64 text-gray-500">
                <UserCircle className="h-12 w-12 sm:h-16 sm:w-16 text-gray-300 mb-2" />
                <p className="mb-2 text-sm">Aucune donnée disponible</p>
              </div>
            )}
          </div>
        </motion.div>
      </div>

      {isBadgeModalOpen && userData && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl shadow-xl max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-[#00717F]">
                Badge du Stagiaire
              </h2>
              <button
                onClick={closeBadgeModal}
                className="text-gray-500 hover:text-gray-700 transition-colors"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="relative w-full max-w-md mx-auto">
              <div className="flex justify-center mb-4 gap-4">
                <button
                  onClick={handleFlip}
                  className="bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-md transition-colors"
                >
                  {isFlipped ? "Voir le recto" : "Voir le verso"}
                </button>
                <button
                  onClick={handleDownloadBadge}
                  className="bg-green-600 hover:bg-green-700 text-white py-2 px-4 rounded-md transition-colors flex items-center gap-2"
                >
                  <Download className="h-4 w-4" />
                  Télécharger
                </button>
              </div>
              <div
                id="badge-container"
                className="relative w-full h-64 perspective-1000"
              >
                <div
                  className={`relative w-full h-full transition-transform duration-700 transform-style-preserve-3d ${
                    isFlipped ? "rotate-y-180" : ""
                  }`}
                >
                  {/* Badge Front */}
                  <div
                    id="badge-front"
                    className={`absolute w-full h-full backface-hidden ${
                      isFlipped ? "invisible" : "visible"
                    }`}
                  >
                    <div className="w-full h-full bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
                      <div className="flex flex-col md:flex-row h-full">
                        {/* Left side - Photo */}
                        <div className="w-full md:w-2/5 bg-gray-100 flex items-center justify-center p-0">
                          {userData.image ? (
                            <img
                              src={`${process.env.REACT_APP_API_URL}${userData.image}`}
                              alt="Profile"
                              className="w-full h-full object-cover"
                              onError={() => {
                                /* eslint-disable */console.error(...oo_tx(`1709345389_515_32_515_75_11`,"Failed to load badge image"));
                                alert("Erreur de chargement de l'image du badge.");
                              }}
                            />
                          ) : (
                            <span className="text-[#333333] text-lg">Photo</span>
                          )}
                        </div>
                        {/* Right side - Information */}
                        <div className="w-full md:w-3/5 p-4 flex flex-col justify-between relative">
                          {/* Background Logo */}
                          <div className="absolute left-11 top-[150px] transform -translate-y-1/2 opacity-30 z-0 flex items-center justify-center w-full">
                            <img
                              src={logo || "/placeholder.svg"}
                              alt="Logo HP ISTA Benguérir"
                              className="w-36 h-36"
                              onError={(e) =>
                                (e.target.src =
                                  "https://placehold.co/200x200/gray/white?text=LOGO+ENTREPRISE")
                              }
                            />
                          </div>

                          {/* Badge header - HP ISTA Benguérir at the top alone */}
                          <div className="text-center mb-3 z-10">
                            <span className="font-semibold text-lg text-[#00717F] tracking-tight">
                              HP ISTA Benguérir
                            </span>
                          </div>

                          <div className="z-10">
                            {/* Name */}
                            <div className="mb-3">
                              <h1 className="text-xl font-bold text-gray-800">
                                {userData.First_Name} {userData.Last_Name}
                              </h1>
                              <p className="text-sm text-red-500">
                                {userData.email.split("@")[0]}
                              </p>
                            </div>

                            {/* Additional info */}
                            <div className="space-y-1">
                              <div className="flex items-center text-xs">
                                <BuildingIcon size={14} className="mr-1 text-[#333333]" />
                                <h3 className="text-gray-700">
                                  {userData.Sector || "Non spécifié"}
                                </h3>
                              </div>
                              <div className="flex items-center text-xs">
                                <MapPinIcon size={14} className="mr-1 text-[#333333]" />
                                <h3 className="text-gray-700">
                                  {userData.emplacement || "Non spécifié"}
                                </h3>
                              </div>
                            </div>
                          </div>

                          {/* STAGIAIRE and CFF moved to bottom before footer */}
                          <div className="mt-auto z-10">
                            <div className="mb-2">
                              <h2 className="text-sm font-semibold uppercase text-[#333333]">
                                STAGIAIRE
                              </h2>
                              <p className="text-xs text-gray-500">{userData.CFF}</p>
                            </div>

                            {/* Footer */}
                            <div className="border-t pt-2">
                              <div className="flex items-center text-xs">
                                <CalendarIcon size={14} className="mr-1 text-[#333333]" />
                                <h3 className="text-[#333333]">
                                  Valide jusqu'au : {formattedValidityDate}
                                </h3>
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Badge Back */}
                  <div
                    id="badge-back"
                    className={`absolute w-full h-full backface-hidden transform rotate-y-180 ${
                      isFlipped ? "visible" : "invisible"
                    }`}
                  >
                    <div className="w-full h-full bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200 flex flex-col">
                      {/* Header */}
                      <div className="bg-blue-600 text-white p-4">
                        <h Grigge2 className="text-lg font-bold">
                          Informations du Stagiaire
                        </h>
                        <p className="text-sm opacity-80">
                          Scannez le code QR pour une vérification numérique
                        </p>
                      </div>
                      {/* QR Code */}
                      <div className="flex-grow flex flex-col items-center justify-center p-4">
                        <div className="bg-white rounded-lg shadow-md">
                          <QRCodeCanvas
                            value={JSON.stringify({
                              id: userData.CFF,
                              name: `${userData.First_Name} ${userData.Last_Name}`,
                              email: userData.email,
                              sector: userData.Sector,
                              role: getTranslatedRole(userData.role),
                              phoneNumber: userData.phoneNumber,
                              parentPhoneNumber: userData.parentPhoneNumber,
                              geographic_criteria: userData.geographic_criteria,
                              Note: userData.Note,
                            })}
                            size={150}
                            level={"H"}
                            includeMargin={true}
                          />
                        </div>
                        <p className="mt-3 text-sm text-center text-[#333333]">
                          {userData.CFF}
                        </p>
                      </div>
                      {/* Contact Information */}
                      <div className="bg-gray-100 p-4">
                        <div className="flex flex-col space-y-2">
                          <div className="flex items-center">
                            <MailIcon size={16} className="mr-2 text-[#333333]" />
                            <span className="text-sm text-gray-700">
                              {userData.email}
                            </span>
                          </div>
                          <div className="flex items-center">
                            <PhoneIcon size={16} className="mr-2 text-[#333333]" />
                            <span className="text-sm text-gray-700">
                              {userData.phoneNumber || "Non spécifié"}
                            </span>
                          </div>
                          <div className="flex items-center">
                            <PhoneIcon size={16} className="mr-2 text-[#333333]" />
                            <span className="text-sm text-gray-700">
                              Contact des parents : {userData.parentPhoneNumber || "Non spécifié"}
                            </span>
                          </div>
                        </div>
                        {/* Company Info */}
                        <div className="mt-4 pt-3 border-t border-gray-300 text-center">
                          <p className="text-xs text-gray-500">
                            En cas de trouvaille, veuillez retourner au siège de
